import { resolveWorkspace, agentIdFromWorktreeName } from './lib/worktree.mjs';
import * as state from './lib/state.mjs';

const WRITE_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit', 'CreateFile']);
const BASH_TOOLS = new Set(['Bash', 'BashOutput']);
const BASH_COMMAND_CLIP = 500;

function allow() {
  process.exit(0);
}

let input;
try {
  input = JSON.parse(readFileSync(0, 'utf8'));
} catch {
  process.stderr.write('fable-opus: scope guard stdin is not valid JSON; allowing the call\n');
  allow();
}

const toolName = input.tool_name;
const isWrite = WRITE_TOOLS.has(toolName);
const isBash = BASH_TOOLS.has(toolName);
if (!isWrite && !isBash) allow();
if (typeof input.cwd !== 'string' || !input.cwd) allow();

const workspace = resolveWorkspace(input.cwd);
const dirs = state.resolveDirs(workspace.projectRoot);

// Attribution routes, in order: the agent id Claude Code puts on the hook input
// when the call comes from a subagent, then the worktree directory name
// (`agent-<id>`, probe-proven for isolation: worktree units).
const agentId =
  (typeof input.agent_id === 'string' && input.agent_id) ||
  agentIdFromWorktreeName(workspace.worktreeName) ||
  null;
if (!agentId) allow();

let binding;
try {
  binding = state.readAgentBinding(dirs, agentId);
} catch {
  binding = null;
}
if (!binding) allow();

const { runId, unitId, attempt, promptPath } = binding;
const workRoot = resolve(binding.workRoot ?? workspace.workRoot);
let runDir;
try {
  runDir = state.runDirFor(dirs, runId);
} catch {
  allow();
}

function mark(detail) {
  try {
    state.markScopeGuard(dirs, agentId, { unitId, runId, attempt, ...detail });
  } catch {
    // The guard's own bookkeeping must never take down a worker's tool call.
  }
}

if (isBash) {
  const command = String(input.tool_input?.command ?? '');
  mark({ tool: toolName, blocked: false });
  appendEvent(runDir, 'scope_bash_observed', unitId, {
    attempt,
    agentId,
    command: command.slice(0, BASH_COMMAND_CLIP),
    // Say the limit out loud in the run record rather than implying coverage.
    enforcement: 'detection only — a shell command can write through paths this hook cannot parse; the SubagentStop git fingerprint is the backstop',
  });
  allow();
}

let contract;
try {
  contract = parseFileContract(readFileSync(promptPath, 'utf8'));
} catch {
  contract = null;
}
// No readable contract means no defensible verdict; the dispatch gate already
// refused packets without one, so this is a torn state, not a permissive one.
if (contract === null) {
  mark({ tool: toolName, blocked: false, note: 'packet file contract unreadable' });
  allow();
}

function targetPaths(toolInput) {
  const raw = [toolInput?.file_path, toolInput?.notebook_path, toolInput?.path];
  if (Array.isArray(toolInput?.edits)) for (const edit of toolInput.edits) raw.push(edit?.file_path);
  return [...new Set(raw.filter((value) => typeof value === 'string' && value))];
}

const targets = targetPaths(input.tool_input);
if (targets.length === 0) {
  mark({ tool: toolName, blocked: false, note: 'no file path in tool input' });
  allow();
}

const offenders = [];
for (const target of targets) {
  const absolute = isAbsolute(target) ? resolve(target) : resolve(workRoot, target);
  const rel = relative(workRoot, absolute);
  if (rel === '' || rel.startsWith('..') || isAbsolute(rel)) {
    offenders.push({ path: target, resolved: absolute, why: 'outside the unit\'s work root' });
    continue;
  }
  if (outsideContract([rel], contract).length > 0) {
    offenders.push({ path: rel, resolved: absolute, why: 'outside the packet file contract' });
  }
}

if (offenders.length === 0) {
  mark({ tool: toolName, blocked: false });
  allow();
}

mark({ tool: toolName, blocked: true });
appendEvent(runDir, 'scope_blocked', unitId, {
  attempt,
  agentId,
  tool: toolName,
  offenders,
  contract,
});
process.stderr.write(
  `fable-opus scope guard: ${toolName} refused — ` +
    offenders.map((o) => `${o.path} is ${o.why}`).join('; ') +
    `. Unit ${unitId} may only write: ${contract.length === 0 ? '(nothing — this is a read-only unit)' : contract.join(', ')}. ` +
    'Needing a file outside your contract is a `blocked` receipt, not an exception.\n',
);
process.exit(2);

